//! Golden bytes: every outbound factory in [`pyatv_proto_mrp::messages`] must serialise to exactly
//! what pyatv's `pyatv/protocols/mrp/messages.py` produces for the same call.
//!
//! The reference bytes come from `tests/kat/mrp_extension_kat.json`, generated by running pyatv
//! itself with `uuid4()` patched to a fixed sequence (see `gen_mrp_extension_kat.py`). The only
//! non-deterministic field in an MRP message is `uniqueIdentifier`, so each test pins ours to the
//! value the vector recorded and then compares the whole serialised envelope byte for byte.
//!
//! This is the check that catches field-ordering, default-suppression and float-width mistakes
//! that a field-by-field assertion would wave through: proto2 lets an encoder omit a field that
//! equals its default, and a device that receives a `DeviceInfoMessage` with a field missing
//! rejects the connection.

mod kat;

use kat::Vector;
use pyatv_core::consts::{RepeatState, ShuffleState};
use pyatv_core::storage::InfoSettings;
use pyatv_proto_mrp::MrpMessage;
use pyatv_proto_mrp::messages::{self, OutputDeviceChange};
use pyatv_proto_mrp::protobuf::{Command, protocol_message::Type};

/// The pairing identifier `gen_mrp_extension_kat.py` pins (`PAIRING_ID` there).
const PAIRING_ID: &str = "89B3D2B7-9D62-4A5C-9E48-2C4F2A0B1D33";

/// Find the vector named `name`; a rename in the generator must fail, not silently skip.
fn vector(name: &str) -> Vector {
    kat::load()
        .into_iter()
        .find(|vector| vector.name == name)
        .unwrap_or_else(|| panic!("no vector named `{name}`"))
}

/// Assert that `message`, once its UUID is pinned, is byte-identical to the vector.
fn assert_matches(name: &str, mut message: MrpMessage) {
    let vector = vector(name);

    message
        .set_unique_identifier(vector.unique_identifier.clone())
        .expect("re-serialising with a pinned uniqueIdentifier");

    assert_eq!(
        message.message_type(),
        vector.message_type,
        "{name}: wrong ProtocolMessage.type ({})",
        vector.type_name
    );
    assert_eq!(
        hex::encode(message.bytes()),
        hex::encode(&vector.protocol_message),
        "{name}: bytes differ from pyatv's ({})",
        vector.note
    );
}

// --- The bring-up sequence -------------------------------------------------
//
// `MrpProtocol.start()` (`pyatv/protocols/mrp/protocol.py:150-170`): DEVICE_INFO, then
// pair-verify when credentials exist, then these three.

#[test]
fn device_information_matches_pyatv() {
    assert_matches(
        "device_info",
        messages::device_information(&InfoSettings::default(), PAIRING_ID, false)
            .expect("building DEVICE_INFO_MESSAGE"),
    );
}

#[test]
fn device_information_update_matches_pyatv() {
    assert_matches(
        "device_info_update",
        messages::device_information(&InfoSettings::default(), PAIRING_ID, true)
            .expect("building DEVICE_INFO_UPDATE_MESSAGE"),
    );
}

