// --- Pairing ---------------------------------------------------------------

/// `is_pairing` is `True` only for pair-setup M1; every other exchange passes `False`.
#[test]
fn crypto_pairing_matches_pyatv() {
    // HAP TLV8: Method(0x00) = 0x00, SeqNo(0x06) = 0x01.
    let tlv = [0x00, 0x01, 0x00, 0x06, 0x01, 0x01];
    assert_matches(
        "crypto_pairing",
        messages::crypto_pairing(&tlv, true).expect("building CRYPTO_PAIRING_MESSAGE"),
    );
}
